  'room.cocina.desc': 'Nutrizione: registra pasti, macro, acqua e il tuo piano settimanale.',
  'room.ejercicio.desc': 'Routine di forza, resistenza e flessibilità con obiettivi.',
  'room.recamara.desc': 'Monitora il tuo riposo e scrivi il tuo diario dei ricordi personale.',
  'room.descanso.desc': 'Il tuo sonno come cielo notturno: programma, sveglia, punteggio e diario notturno.',
