  'room.despacho.desc':
    'Finanze: budget con spese ed entrate (fisse e variabili), obiettivi (calcolatrici finanziarie, risparmio/investimenti, debiti) con simulatori, e mercati in tempo reale.',
  'room.biblioteca.desc': 'Enciclopedia conversazionale: chat con l\'IA, voci wiki e sessioni di studio.',
  'room.entretenimiento.desc': 'Archivio di film, serie, libri e giochi da tavolo.',
  'room.sala.desc': 'Pianifica viaggi: itinerario, spese, checklist e lista dei desideri.',
  'room.jardin.desc': 'Calma: meditazioni guidate, respirazione e diario della gratitudine.',
  'room.garage.desc': 'Manutenzione dei tuoi veicoli e dei loro interventi.',
