  'tut.appSinCuarto':
    'Questa app non è ancora in nessuna stanza, quindi te la spiego da qui. Per usarla, assegnala in Menu › Modelli.',
  'tut.errorCarga': 'Non sono riuscito a caricare questo tutorial. Controlla la tua connessione e riprova.',
  'tut.preparandoDemo': 'Sto preparando l\'anno di quell\'app nella casa demo; il tour inizia tra pochi secondi…',
  'tut.selector.titulo': 'Quale tutorial vuoi vedere?',
  'tut.selector.hint': 'Tocca una zona evidenziata in giallo, oppure inizia da quello generale.',
  'tut.selector.general': 'Tutorial generale',
