  'demo.aviso.titulo': 'Sei nella casa demo',
  'demo.aviso.cuerpo':
    'Prova tutto: puoi modificare la casa e usare le app con dentro un anno della vita di Pep. Niente viene salvato — ricaricando, la casa torna com\'era.',
  'demo.aviso.seguir': 'Continua a esplorare',
